#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    if (n >= 100) {
        cout << 0 << "\n";
    } else {
        vector<vector<int>> pts(n + 1, vector<int>(5));
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < 5; j++) {
                cin >> pts[i][j];
            }
        }
        unordered_set<int> badSet;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                for (int k = 1; k <= n; k++) {
                    if (i == j || j == k || k == i) continue;
                    std::vector<long long> v1(5), v2(5);
                    for (int m = 0; m < 5; m++) {
                        v1[m] = pts[j][m] - pts[i][m];
                        v2[m] = pts[k][m] - pts[i][m];
                    }
                    double dotProd = 0.0;
                    long long magV1 = 0, magV2 = 0;
                    for (int m = 0; m < 5; m++) {
                        dotProd += v1[m] * v2[m];
                        magV1 += v1[m] * v1[m];
                        magV2 += v2[m] * v2[m];
                    }
                    double denom = std::sqrt((double)magV1) * std::sqrt((double)magV2);
                    if (denom == 0) continue; // avoid division by zero
                    double cosTheta = dotProd / denom;
                    // Clamp cosTheta to [-1,1] to avoid domain errors in acos
                    if (cosTheta > 1.0) cosTheta = 1.0;
                    if (cosTheta < -1.0) cosTheta = -1.0;
                    double angleDeg = std::acos(cosTheta) * 180.0 / M_PI;
                    if (angleDeg + 1e-9 < 90.0) {
                        badSet.insert(i);
                    }
                }
            }
        }
        cout << n - (int)badSet.size() << "\n";
        for (int i = 1; i <= n; i++) {
            if (badSet.find(i) == badSet.end()) {
                cout << i << "\n";
            }
        }
    }
    return 0;
}
